"use client";

import { useEffect } from "react";
import ActiveEffects from "@/components/game/ActiveEffects";
import BossHealthBar from "@/components/game/BossHealthBar";
import DeathScreen from "@/components/game/DeathScreen";
import DebugOverlay from "@/components/game/DebugOverlay";
import GameOverScreen from "@/components/game/GameOverScreen";
import Hotbar from "@/components/game/Hotbar";
import InventoryPanel from "@/components/game/InventoryPanel";
import PauseMenu from "@/components/game/PauseMenu";
import SleepOverlay from "@/components/game/SleepOverlay";
import StatusBars from "@/components/game/StatusBars";
import VictoryScreen from "@/components/game/VictoryScreen";
import XpBar from "@/components/game/XpBar";
import { ENCHANT_COST_LEVELS } from "@/lib/game/config";
import type { Profile } from "@/lib/game/profiles";
import { useMinecraftGame } from "@/lib/game/useMinecraftGame";
import { takesDamage, usesInventory } from "@/lib/game/gameModes";
import type { WorldMeta } from "@/lib/game/worlds";
import { installUiTiles } from "@/lib/ui/chromeTiles";

type MinecraftGameProps = {
  world: WorldMeta;
  profile: Profile;
  onQuitToWorlds: () => void;
  /** Hardcore Game Over: erase the dead world and return to the world list. */
  onDeleteWorld: () => void;
  onReloadWorld: () => void;
};

export default function MinecraftGame({ world, profile, onQuitToWorlds, onDeleteWorld, onReloadWorld }: MinecraftGameProps) {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    gameMode,
    difficulty,
    hardcore,
    gameOver,
    giveCreativeItem,
    setGameMode,
    setDifficulty,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
    daylightPercent,
    passiveCount,
    hostileCount,
    respawnSeconds,
    paused,
    sleeping,
    craftingStation,
    container,
    boss,
    victory,
    activeEffects,
    xpLevel,
    xpProgress,
    debugOpen,
    debug,
    saveMessage,
    audioSettings,
    updateAudioSettings,
    skinId,
    updateSkin,
    hotbarSlots,
    recipes,
    maxHearts,
    maxHunger,
    maxOxygen,
    canCraft,
    craft,
    enchant,
    swapInventorySlots,
    moveStack,
    toggleEquipArmor,
    resumeNow,
    respawnNow,
    dismissVictory,
    saveNow,
    loadNow,
    resetNow,
    quitToWorlds
  } = useMinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld });

  useEffect(() => {
    installUiTiles();
  }, []);

  if (rendererError) {
    return (
      <div className="game-root">
        <div className="renderer-error">
          <h2>Could not start the 3D renderer</h2>
          <p>WebGL appears to be unavailable in this browser ({rendererError}).</p>
          <p>Try enabling hardware acceleration or switching browsers, then reload.</p>
        </div>
      </div>
    );
  }

  const showClickHint = !locked && !paused && !inventoryOpen && respawnSeconds === 0;

  return (
