1	import { describe, expect, mock, test } from "bun:test";
2	import { render, screen } from "@testing-library/react";
3	import userEvent from "@testing-library/user-event";
4	import InventoryPanel from "@/components/game/InventoryPanel";
5	import { CHEST_SLOTS, HOTBAR_SLOTS, INVENTORY_SLOTS } from "@/lib/game/config";
6	import { CONTAINER_SLOT_BASE } from "@/lib/game/engine/commands";
7	import { createEmptyArmorEquipment, createEmptySlot, createSlot } from "@/lib/game/items";
8	import { RECIPES } from "@/lib/game/recipes";
9	import type { GameMode } from "@/lib/game/gameModes";
10	import type { InventorySlot } from "@/lib/game/types";
11	
12	function makeInventory(...items: Array<[string, number] | null>): InventorySlot[] {
13	  const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
14	  items.forEach((item, i) => {
15	    if (item) slots[i] = createSlot(item[0], item[1]);
16	  });
17	  return slots;
18	}
19	
20	function renderPanel(overrides: Partial<Parameters<typeof InventoryPanel>[0]> = {}) {
21	  const props = {
22	    inventory: makeInventory(["dirt", 10], ["stone", 5], ["helmet", 1]),
23	    equippedArmor: createEmptyArmorEquipment(),
24	    selectedHotbarSlot: 0,
25	    hotbarSlots: HOTBAR_SLOTS,
26	    recipes: RECIPES,
27	    craftingStation: null as "furnace" | "enchanting" | null,
28	    gameMode: "survival" as GameMode,
29	    container: null as InventorySlot[] | null,
30	    xpLevel: 0,
31	    enchantCost: 3,
32	    canCraft: () => true,
33	    onSwapSlots: mock(),
34	    onMoveStack: mock(),
35	    onToggleEquipArmor: mock(),
36	    onCraft: mock(),
37	    onEnchant: mock(),
38	    onGiveItem: mock(),
39	    ...overrides
40	  };
41	  render(<InventoryPanel {...props} />);
42	  return props;
43	}
44	
45	function slotButtons() {
46	  // Inventory slot wells, excluding the armor column and recipe entries.
47	  return screen.getAllByRole("button").filter((button) => button.className.includes("inv-slot") && !button.className.includes("armor-slot"));
48	}
49	
50	function recipeOrder() {
51	  // The recipe entries in DOM order, identified by their aria-label (the recipe label).
52	  return screen
53	    .getAllByRole("button")
54	    .filter((button) => button.className.includes("recipe-entry"))
55	    .map((button) => button.getAttribute("aria-label"));
56	}
57	
58	describe("InventoryPanel", () => {
59	  test("renders all inventory slots plus recipe buttons", () => {
60	    renderPanel();
61	    expect(slotButtons()).toHaveLength(INVENTORY_SLOTS);
62	    expect(screen.getByRole("button", { name: "2 Wood -> 4 Planks" })).toBeTruthy();
63	  });
64	
65	  test("recipes are grouped under category headers in the fixed display order", () => {
66	    renderPanel();
67	    const headers = screen.getAllByText(/^(Tools|Weapons|Armor|Building|Food|Materials|Smelting|Trades)$/).map((el) => el.textContent);
68	    // Every group is present (each category has at least one recipe) and ordered.
69	    expect(headers).toEqual(["Tools", "Weapons", "Armor", "Building", "Food", "Materials", "Smelting", "Trades"]);
70	  });
71	
72	  test("craftable-now recipes sort above locked ones within a group", () => {
73	    const stone = RECIPES.find((recipe) => recipe.id === "stone_pickaxe")!;
74	    const wood = RECIPES.find((recipe) => recipe.id === "wood_pickaxe")!;
75	    renderPanel({ canCraft: (recipe) => recipe.id === "stone_pickaxe" });
76	    const order = recipeOrder();
77	    // Both are Tools; only the stone pickaxe is craftable, so it floats above the wood one.
78	    expect(order.indexOf(stone.label)).toBeLessThan(order.indexOf(wood.label));
79	  });
80	
81	  test("slots are ordered storage first, hotbar row last, with icons and counts", () => {
82	    renderPanel();
83	    const slots = slotButtons();
84	    // DOM order: the 27 storage slots (indices 9..35) render above the hotbar row (0..8).
85	    expect(slots[27].getAttribute("aria-label")).toBe("Slot 1: Dirt");
86	    // Dirt appears as the slot icon and again inside recipe ingredients.
87	    expect(screen.getAllByAltText("Dirt").length).toBeGreaterThan(0);
88	    expect(screen.getByText("10")).toBeTruthy(); // the dirt stack count
89	  });
90	
91	  test("clicking two slots swaps them via onSwapSlots", async () => {
92	    const user = userEvent.setup();
93	    const props = renderPanel();
94	    const slots = slotButtons();
95	
96	    await user.click(slots[0]); // pending — first storage slot, inventory index 9
97	    expect(slots[0].className).toContain("pending");
98	    await user.click(slots[1]);
99	    expect(props.onSwapSlots).toHaveBeenCalledWith(9, 10);
100	  });
101	
102	  test("clicking the same slot twice cancels the pending selection", async () => {
103	    const user = userEvent.setup();
104	    const props = renderPanel();
105	    const slots = slotButtons();
106	
107	    await user.click(slots[0]);
108	    await user.click(slots[0]);
109	    expect(slots[0].className).not.toContain("pending");
110	    expect(props.onSwapSlots).not.toHaveBeenCalled();
111	
112	    await user.click(slots[1]); // a fresh click starts a new pending selection
113	    expect(props.onSwapSlots).not.toHaveBeenCalled();
114	  });
115	
116	  test("clicking an armor item toggles equipment instead of swapping", async () => {
117	    const user = userEvent.setup();
118	    const props = renderPanel();
119	    const slots = slotButtons();
120	
121	    await user.click(slots[27 + 2]); // the helmet sits in hotbar slot 2
122	    expect(props.onToggleEquipArmor).toHaveBeenCalledWith(2);
123	    expect(props.onSwapSlots).not.toHaveBeenCalled();
124	  });
125	
126	  test("equipped armor is shown in its armor slot with durability and unequips on click", async () => {
127	    const user = userEvent.setup();
128	    const props = renderPanel({ equippedArmor: { ...createEmptyArmorEquipment(), helmet: "helmet" } });
129	    const helmetSlot = screen.getByRole("button", { name: "Helmet: Helmet" });
130	    expect(helmetSlot.className).toContain("filled");
131	    await user.hover(helmetSlot);
