2	import ItemIcon from "@/components/game/ItemIcon";
3	import { canMaterialRepair, findSacrificeIndex, isAnvilGear, repairMaterialFor, sanitizeCustomName, wouldCombineHelp } from "@/lib/game/anvil";
4	import { CUSTOM_NAME_MAX_LEN } from "@/lib/game/config";
5	import { displayName, ITEM_DEF_BY_ID } from "@/lib/game/items";
6	import type { InventorySlot } from "@/lib/game/types";
7	
8	type AnvilColumnProps = {
9	  /** The selected hotbar item to repair/combine/rename (or undefined/empty). */
10	  item: InventorySlot | undefined;
11	  /** Full inventory, to detect a combine duplicate and the repair material. */
12	  inventory: InventorySlot[];
13	  selectedHotbarSlot: number;
14	  xpLevel: number;
15	  combineCost: number;
16	  repairCost: number;
17	  renameCost: number;
18	  onCombine: () => void;
19	  onRepair: () => void;
20	  onRename: (name: string) => void;
21	};
22	
23	const labelFor = (slotId: string): string => ITEM_DEF_BY_ID[slotId]?.label ?? slotId;
24	
25	/**
26	 * The anvil panel (replaces the recipe book while an anvil is open): repair,
27	 * combine, or rename the selected hotbar gear, each spending XP levels. Mirrors
28	 * the enchanting panel — it acts on whichever hotbar slot is selected.
29	 */
30	export default function AnvilColumn({
31	  item,
32	  inventory,
33	  selectedHotbarSlot,
34	  xpLevel,
35	  combineCost,
36	  repairCost,
37	  renameCost,
38	  onCombine,
39	  onRepair,
40	  onRename
41	}: AnvilColumnProps) {
42	  const gear = isAnvilGear(item);
43	  // Reset the rename field whenever the targeted item changes — keyed on the saved
44	  // name too, so swapping in a same-id item with a different name refreshes it.
45	  const fieldKey = `${selectedHotbarSlot}:${item?.id ?? ""}:${item?.customName ?? ""}`;
46	  const [nameField, setNameField] = useState({ key: fieldKey, value: item?.customName ?? "" });
47	  const name = nameField.key === fieldKey ? nameField.value : (item?.customName ?? "");
48	  const setName = (value: string) => setNameField({ key: fieldKey, value });
49	
50	  if (!gear || !item) {
51	    return (
52	      <div className="anvil-column">
53	        <div className="inventory-heading">Anvil</div>
54	        <div className="enchanting-hint">Select a tool, weapon, or armor in the hotbar to repair or rename it.</div>
55	      </div>
56	    );
57	  }
58	
59	  const max = item.maxDurability ?? 0;
60	  const durability = item.durability ?? max;
61	
62	  const sacrificeIndex = findSacrificeIndex(inventory, selectedHotbarSlot);
63	  const hasDuplicate = sacrificeIndex >= 0;
64	  const combineHelps = hasDuplicate && wouldCombineHelp(item, inventory[sacrificeIndex]);
65	  const combineEnabled = combineHelps && xpLevel >= combineCost;
66	  const combineStatus = !hasDuplicate
67	    ? `Need a second ${displayName(item)} to combine`
68	    : !combineHelps
69	      ? "Already at full durability and enchantments"
70	      : xpLevel < combineCost
71	        ? "Not enough XP"
72	        : `Costs ${combineCost} levels`;
73	
74	  const material = repairMaterialFor(item);
75	  const repairable = canMaterialRepair(item, inventory);
76	  const repairEnabled = repairable && xpLevel >= repairCost;
77	  const repairStatus = !material
78	    ? "No repair material for this item"
79	    : durability >= max
80	      ? "Already at full durability"
81	      : !repairable
82	        ? `Need ${labelFor(material)} to repair`
83	        : xpLevel < repairCost
84	          ? "Not enough XP"
85	          : `Costs ${repairCost} levels`;
86	
87	  const trimmed = name.trim();
88	  const renameChanged = trimmed !== (item.customName ?? "");
89	  const renameEnabled = renameChanged && xpLevel >= renameCost;
90	
91	  return (
92	    <div className="anvil-column">
93	      <div className="inventory-heading">Anvil</div>
94	      <div className="enchanting-item">
95	        <ItemIcon slot={item} size={32} />
96	        <span>{displayName(item)}</span>
97	      </div>
98	      <div className="enchanting-cost">
99	        Durability {durability} / {max} · you have {xpLevel} levels
100	      </div>
101	      <div className="anvil-actions">
102	        <button className="anvil-action" onClick={onCombine} disabled={!combineEnabled} aria-label={`Combine duplicate — ${combineStatus}`}>
103	          <span className="enchant-name">Combine duplicate</span>
104	          <span className="enchant-cost">{hasDuplicate ? `${combineCost} lvl` : "—"}</span>
105	        </button>
106	        <div className="anvil-status">{combineStatus}</div>
107	        <button className="anvil-action" onClick={onRepair} disabled={!repairEnabled} aria-label={`Repair with material — ${repairStatus}`}>
108	          <span className="enchant-name">Repair{material ? ` with ${labelFor(material)}` : ""}</span>
109	          <span className="enchant-cost">{material ? `${repairCost} lvl` : "—"}</span>
110	        </button>
111	        <div className="anvil-status">{repairStatus}</div>
112	        <label className="anvil-rename-field">
113	          <span className="enchant-name">Rename</span>
114	          <input
115	            type="text"
116	            value={name}
117	            maxLength={CUSTOM_NAME_MAX_LEN}
118	            placeholder={item.label}
119	            onChange={(e) => setName(e.target.value)}
120	            aria-label="Custom item name"
121	          />
122	        </label>
123	        <button
124	          className="anvil-action"
125	          onClick={() => onRename(sanitizeCustomName(name))}
126	          disabled={!renameEnabled}
127	          aria-label={`Apply rename — costs ${renameCost} levels`}
128	        >
129	          <span className="enchant-name">{trimmed ? "Apply name" : "Clear name"}</span>
130	          <span className="enchant-cost">{renameCost} lvl</span>
131	        </button>
132	      </div>
133	    </div>
134	  );
135	}

