  const v11: SaveDataV11 = {
    ...v5Save(),
    version: 11,
    inventorySlots: [{ id: "helmet", count: 1, durability: 200, enchantments: [{ id: "protection", level: 2 }] }, { id: "dirt", count: 5 }],
