78	/**
79	 * Wears the tool/weapon at `index` by `amount`; the slot empties at zero
80	 * durability. When `rng` is supplied, an Unbreaking enchant may skip the wear
81	 * (returning null — no change — like an inapplicable op).
82	 */
83	export function consumeToolDurability(slots: InventorySlot[], index: number, amount = 1, rng?: () => number): InventorySlot[] | null {
84	  if (amount <= 0) return null;
85	  if (index < 0 || index >= slots.length) return null;
86	  const next = cloneSlots(slots);
87	  const slot = next[index];
88	  if ((slot.kind !== "tool" && slot.kind !== "weapon") || !slot.id || slot.count <= 0 || !slot.maxDurability) return null;
89	  if (rng && unbreakingSkips(slot, rng)) return null; // Unbreaking saved a point of wear
90	  const nextDurability = (slot.durability ?? slot.maxDurability) - amount;
91	  if (nextDurability <= 0) {
92	    next[index] = createEmptySlot();
93	    return next;
94	  }
95	  slot.durability = nextDurability;
96	  return next;
97	}
