99	/**
100	 * Wears every worn armor piece by `amount`; a piece that hits zero durability
101	 * breaks (its slot becomes null). When `rng` is supplied, each piece's Unbreaking
102	 * enchant may skip its wear. Returns a new record, or null when nothing changed.
103	 */
104	export function consumeEquippedArmorDurability(equipped: EquippedArmor, amount = 1, rng?: () => number): EquippedArmor | null {
105	  if (amount <= 0) return null;
106	  const next = { ...equipped };
107	  let changed = false;
108	  for (const armorSlot of ARMOR_SLOTS) {
109	    const piece = next[armorSlot];
110	    if (!piece?.maxDurability) continue;
111	    if (rng && unbreakingSkips(piece, rng)) continue; // this piece's Unbreaking saved its wear
112	    const nextDurability = (piece.durability ?? piece.maxDurability) - amount;
113	    next[armorSlot] = nextDurability <= 0 ? null : { ...piece, durability: nextDurability };
114	    changed = true;
115	  }
116	  return changed ? next : null;
117	}
