124	 * Drives the recipe-book tooltip that shows what an unaffordable recipe is missing.
125	 */
126	export function ingredientStatus(slots: InventorySlot[], recipe: Recipe): IngredientStatus[] {
127	  const byId = countsById(slots);
128	  return recipe.cost.map((cost) => ({ slotId: cost.slotId, have: byId.get(cost.slotId) ?? 0, need: cost.count }));
129	}
