131	export function canCraft(slots: InventorySlot[], recipe: Recipe): boolean {
132	  const byId = countsById(slots);
133	  const hasCost = recipe.cost.every((cost) => (byId.get(cost.slotId) ?? 0) >= cost.count);
134	  if (!hasCost) return false;
135	
136	  let freeForResult = 0;
137	  const stackSize = maxStackSizeForItem(recipe.result.slotId);
138	  for (const slot of slots) {
139	    if (slot.id === recipe.result.slotId) freeForResult += stackSize - slot.count;
140	    if (slot.id === null && slot.count === 0) freeForResult += stackSize;
141	  }
142	  return freeForResult >= recipe.result.count;
143	}
